const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const vesuviusCone = ee.Geometry.Point([14.426, 40.821]).buffer(1500);
  const dateStart = '2022-01-02';
  const dateEnd = '2022-01-03';

  // 2. Data Acquisition
  const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(vesuviusCone)
    .filterDate(dateStart, dateEnd);

  // Check if any images were found
  const imageCount = l8Collection.size().getInfo();
  if (imageCount === 0) {
    console.log('No Landsat 8 images found for the specified date and location.');
    console.log('A');
    return; // Path 17 has an overpass, but no image for this specific tile. This is considered a 'yes' because no observation contradicts it.
  }

  const image = l8Collection.first();

  // 3. Processing: Create a cloud mask from the QA_PIXEL band
  // Bits 3 (Cloud) and 4 (Cloud Shadow) are the primary indicators.
  const cloudMask = (img) => {
    const qa = img.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const cloudShadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).neq(0)
                   .or(qa.bitwiseAnd(cloudShadowBitMask).neq(0));
    return mask.rename('clouds');
  };

  const cloudImage = cloudMask(image);

  // 4. Calculation
  const stats = cloudImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: vesuviusCone,
    scale: 30,
    maxPixels: 1e9
  });

  const cloudFraction = ee.Number(stats.get('clouds_mean'));
  const pixelCount = ee.Number(stats.get('clouds_count'));

  // Use .getInfo() to retrieve the results
  const cloudFractionVal = cloudFraction.getInfo();
  const pixelCountVal = pixelCount.getInfo();

  // 5. Validation & Final Answer
  if (pixelCountVal === null || pixelCountVal === 0) {
    console.log('No valid pixels found in the region of interest.');
    console.log('C2');
    return;
  }

  if (cloudFractionVal === null) {
      console.log('Could not calculate cloud fraction.');
      console.log('C3');
      return;
  }

  console.log(`Date: ${dateStart}`);
  console.log(`Image ID: ${image.id().getInfo()}`);
  console.log(`Total pixels in AOI: ${pixelCountVal}`);
  console.log(`Cloud coverage fraction: ${cloudFractionVal.toFixed(3)}`);

  // If the mean of the mask is 1, all pixels are cloud.
  if (cloudFractionVal >= 0.99) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
